/// One level range clamped, or `None` when it must go.
fn clamp_level(level: LevelRange) -> Option<LevelRange> {
    if level.low.is_nan() || level.high.is_nan() || level.softness.is_nan() {
        return None;
    }
    let low = level.low.clamp(0.0, 1.0);
    Some(LevelRange {
        low,
        high: level.high.clamp(0.0, 1.0).max(low),
        softness: level.softness.clamp(0.0, 1.0),
    })
}

pub(crate) fn clamp_audio(mut props: AudioProps) -> AudioProps {
    props.volume = bounded(props.volume, 0.0, MAX_GAIN, 1.0);
    props.fade_in = props.fade_in.max(0);
    props.fade_out = props.fade_out.max(0);
    if let Some(duck) = props.duck.as_mut() {
        duck.level = bounded(duck.level, 0.0, 1.0, 0.2);
        duck.attack = duck.attack.max(0);
        duck.release = duck.release.max(0);
    }
    // Pan's neutral is the CENTRE, not either end: a NaN that silently
    // threw the voice into one speaker would be worse than one that did
    // nothing.
    props.pan = bounded(props.pan, -1.0, 1.0, 0.0);
        )?;
    }
    Ok(())
}

/// The audio group. Its six tick values — the two fades, the duck's and the
/// compressor's attack and release — are the one family the Times rule
/// deliberately leaves OFF the frame grid (core/CLAUDE.md): they are
/// envelope lengths sampled at the audio rate rather than positions in the
/// picture, and a 10 ms compressor attack quantised to a video frame would
/// round to nothing. Only the sign is checked, as it is for a motion
/// duration.
pub(crate) fn check_audio(props: &AudioProps) -> Result<(), String> {
    in_range("audio.volume", props.volume, 0.0, MAX_GAIN)?;
    ticks_positive_or_zero("audio.fade_in", props.fade_in)?;
    ticks_positive_or_zero("audio.fade_out", props.fade_out)?;
    if let Some(duck) = &props.duck {
        in_range("audio.duck.level", duck.level, 0.0, 1.0)?;
        ticks_positive_or_zero("audio.duck.attack", duck.attack)?;
        ticks_positive_or_zero("audio.duck.release", duck.release)?;
    }
    Overlay,
    Darken,
    Lighten,
    Difference,
}

