import AVFoundation

// Reads the sample through an AVAudioMix at a given volume (ramp form, as the
// app sets it) in 32-bit float and reports the peak, so the ratio between two
// volumes says whether the mix applies gains above 4.
let url = URL(fileURLWithPath: CommandLine.arguments[1])
let asset = AVURLAsset(url: url)
let sem = DispatchSemaphore(value: 0)
nonisolated(unsafe) var srcTrack: AVAssetTrack?
nonisolated(unsafe) var duration = CMTime.zero
Task {
    srcTrack = try? await asset.loadTracks(withMediaType: .audio).first
    duration = (try? await asset.load(.duration)) ?? .zero
    sem.signal()
}
sem.wait()
guard let srcTrack else { fatalError("no audio track") }

func peak(volume: Float) -> Float {
    let comp = AVMutableComposition()
    let t = comp.addMutableTrack(withMediaType: .audio, preferredTrackID: kCMPersistentTrackID_Invalid)!
    try! t.insertTimeRange(CMTimeRange(start: .zero, duration: duration), of: srcTrack, at: .zero)
    let p = AVMutableAudioMixInputParameters(track: t)
    p.setVolumeRamp(fromStartVolume: volume, toEndVolume: volume,
                    timeRange: CMTimeRange(start: .zero, duration: duration))
    let mix = AVMutableAudioMix()
    mix.inputParameters = [p]
    let reader = try! AVAssetReader(asset: comp)
    let out = AVAssetReaderAudioMixOutput(audioTracks: [t], audioSettings: [
        AVFormatIDKey: kAudioFormatLinearPCM, AVLinearPCMBitDepthKey: 32,
        AVLinearPCMIsFloatKey: true, AVLinearPCMIsNonInterleaved: false,
        AVLinearPCMIsBigEndianKey: false, AVSampleRateKey: 48000, AVNumberOfChannelsKey: 1])
    out.audioMix = mix
    reader.add(out)
    reader.startReading()
    var best: Float = 0
    while let sb = out.copyNextSampleBuffer() {
        guard let block = CMSampleBufferGetDataBuffer(sb) else { continue }
        var length = 0
        var ptr: UnsafeMutablePointer<CChar>?
        CMBlockBufferGetDataPointer(
            block, atOffset: 0, lengthAtOffsetOut: nil, totalLengthOut: &length,
            dataPointerOut: &ptr)
        ptr!.withMemoryRebound(to: Float.self, capacity: length / 4) { f in
            for i in 0..<(length / 4) { best = max(best, abs(f[i])) }
        }
    }
    return best
}

let base = peak(volume: 1)
for v: Float in [1, 4, 7.6, 16, 32, 64] {
    let p = peak(volume: v)
    print(String(format: "volume %5.1f  peak %.5f  %+6.2f dBFS  ratio %.3f", v, p, 20 * log10(p), p / base))
}

