      log(`lane ${L.lane}: ${L.batches[i].dir} ${r.status} with uncommitted work; lane halted`)
      for (const rest of L.batches.slice(i + 1)) out.push({ dir: rest.dir, issues: rest.issues, status: 'not-run', detail: `lane halted at ${L.batches[i].dir}` })
      break
    }
  }
  return { lane: L.lane, results: out }
}

